const webhookItem = $('Webhook').item;
let rawBody;
if (webhookItem.binary && webhookItem.binary.data) {
  rawBody = Buffer.from(webhookItem.binary.data.data, 'base64').toString('utf8');
} else {
  rawBody = JSON.stringify(webhookItem.json.body);
}
const headers = webhookItem.json.headers || {};
const signature = headers['x-ifood-signature'] || headers['X-IFood-Signature'] || '';
return items.map(i => ({ json: { ...i.json, rawBody, signature } }));

const signature = items[0] ? items[0].json.signature : null;
const rawBody = items[0] ? items[0].json.rawBody : null;
const match = items.find(i => {
  const computed = i.json.data || i.json.hash || i.json.hmac || i.json.value;
  return computed && signature && String(computed).toLowerCase() === String(signature).toLowerCase();
});
return [{
  json: {
    assinatura_valida: !!match,
    rawBody,
    empresa_id: match ? match.json.empresa_id : null,
    id_loja_plataforma: match ? match.json.id_loja_plataforma : null,
    api_key: match ? match.json.api_key : null,
    api_secret: match ? match.json.api_secret : null,
  },
}];

const ev = JSON.parse($json.rawBody);
return [{
  json: {
    ...ev,
    empresa_id: $json.empresa_id,
    id_loja_plataforma: $json.id_loja_plataforma,
    api_key: $json.api_key,
    api_secret: $json.api_secret,
  },
}];

const empresaId = $json.empresa_id;
const store = $getWorkflowStaticData('global');
store.ifoodTokens = store.ifoodTokens || {};
const cached = store.ifoodTokens[empresaId];
const valido = !!(cached && cached.expiresAt > Date.now() + 60000);
return [{
  json: {
    ...$json,
    access_token: valido ? cached.accessToken : null,
    token_valido: valido,
  },
}];

const ctx = $('Checar token em cache').item.json;
const store = $getWorkflowStaticData('global');
store.ifoodTokens = store.ifoodTokens || {};
store.ifoodTokens[ctx.empresa_id] = {
  accessToken: $json.accessToken,
  expiresAt: Date.now() + (($json.expiresIn || 21600) * 1000),
};
return [{
  json: { ...ctx, access_token: $json.accessToken, token_valido: true },
}];

const ev = $('Switch por tipo de evento').item.json;
const order = $json;
const phone = order.customer?.phone?.number || '';
// Endereço real vem aninhado em order.delivery.deliveryAddress, não em
// order.deliveryAddress (esse caminho nunca existe na resposta da iFood).
const address = order.delivery?.deliveryAddress || {};
const doc = order.customer?.documentType === 'CPF' ? order.customer?.documentNumber : null;
return [{
  json: {
    empresa_id: ev.empresa_id,
    orderId: ev.orderId,
    access_token: ev.access_token,
    order,
    cliente: {
      nome: order.customer?.name || 'Cliente iFood',
      telefone: phone,
      // customer.id é estável por cliente real (confirmado: pedidos com
      // telefones mascarados diferentes compartilham o mesmo customer.id)
      // - chave de casamento, não o telefone (que a iFood reaproveita entre
      // pedidos/clientes diferentes).
      idExternoIfood: order.customer?.id || null,
      cpf: doc,
      endereco: address.streetName || '',
      numero: address.streetNumber || '',
      bairro: address.neighborhood || '',
      cidade: address.city || '',
      estado: address.state || '',
      cep: address.postalCode || '',
      complemento: address.complement || null,
      latitude: address.coordinates?.latitude ?? null,
      longitude: address.coordinates?.longitude ?? null,
    },
  },
}];

const found = $('Buscar cliente existente').item.json;
const cliente_id = found.id || $json.id;
return [{ json: { ...$('Preparar dados do cliente').item.json, cliente_id } }];

const ctx = $json;
const items = ctx.order.items || [];
return items.map(it => ({
  json: {
    empresa_id: ctx.empresa_id,
    cliente_id: ctx.cliente_id,
    orderId: ctx.orderId,
    order: ctx.order,
    item_externo_id: String(it.id),
    uniqueid_marketplace: it.uniqueId,
    nome_item: it.name,
    quantidade: it.quantity,
    preco_unitario: (it.totalPrice ?? it.unitPrice ?? 0) / (it.quantity || 1),
    subtotal: it.totalPrice ?? ((it.unitPrice || 0) * (it.quantity || 1)),
    observacao_cliente: it.observations || null,
  },
}));

const direct = $('Resolver produto_id').item.json.produto_id;
let produtoId = direct;
let naoCatalogado = false;
if (!produtoId) {
  naoCatalogado = true;
  const existing = $('Buscar placeholder existente').item.json.id;
  produtoId = existing || $json.id;
}
return [{ json: { ...$('Explodir itens do pedido').item.json, produto_id: produtoId, item_nao_catalogado: naoCatalogado } }];

const list = items.map(i => i.json);
return [{
  json: {
    empresa_id: list[0]?.empresa_id,
    cliente_id: list[0]?.cliente_id,
    orderId: list[0]?.orderId,
    order: list[0]?.order,
    itens: list,
    algum_nao_catalogado: list.some(i => i.item_nao_catalogado),
  },
}];

const ctx = $json;
const order = ctx.order;
const metodoMap = { CREDIT: 'Cartão de Crédito', DEBIT: 'Cartão de Débito', PIX: 'Pix', CASH: 'Dinheiro' };
// Múltiplos métodos de pagamento num só pedido (ex: parte prepago no app
// + parte em dinheiro na entrega) nunca visto num pedido real ainda -
// generalização defensiva, não confirmada contra payload real. Rótulo
// concatena os tipos únicos em vez de só olhar methods[0].
const methods = order.payments?.methods || [];
const allPrepaid = methods.length > 0 && methods.every(m => m.type === 'PREPAID');
const anyOffline = methods.some(m => m.type === 'OFFLINE');
const tipoPagamento = methods.length === 0 ? 'Outros'
  : allPrepaid ? 'iFood'
  : [...new Set(methods.map(m => m.type === 'PREPAID' ? 'iFood' : (metodoMap[m.method] || 'Outros')))].join(' + ');
const statusPagamento = anyOffline ? 'pendente' : 'pago';
const cashMethod = methods.find(m => m.method === 'CASH');
const total = order.total || {};
// Confirmado com pedido TAKEOUT real 2026-07-29: order.takeout tem forma
// bem diferente de order.delivery (mode/location/takeoutDateTime, sem
// pickupCode - o código de retirada do courier só existe em DELIVERY).
const isTakeout = order.orderType === 'TAKEOUT';
const pickupCodeEntrega = order.delivery?.pickupCode ?? null;
const dataHoraImediata = isTakeout ? (order.takeout?.takeoutDateTime ?? null) : (order.delivery?.deliveryDateTime ?? null);
let observacoes = order.orderTiming === 'SCHEDULED' ? 'Pedido agendado (iFood).' : '';
if (ctx.algum_nao_catalogado) {
  observacoes += ' Contém item não catalogado, revisar catálogo do iFood.';
}
const changeFor = cashMethod?.cash?.changeFor ?? null;
// pending = valor real a cobrar fora do app da iFood - correto mesmo em
// pagamento misto (prepago + dinheiro); só coincide com orderAmount
// inteiro quando o pedido inteiro é pago em dinheiro (caso observado
// até agora).
const valorPendente = order.payments?.pending ?? (total.orderAmount ?? 0);
const troco = changeFor != null ? Math.max(0, changeFor - valorPendente) : null;
const taxaServicoCliente = (order.additionalFees || []).reduce((acc, f) => acc + (f.value || 0), 0);
// Cupom/campanha: order.benefits[] (confirmado com pedido real 2026-07-29,
// campaign.id/name + sponsorshipValues por patrocinador IFOOD/MERCHANT/
// EXTERNAL/CHAIN). Só o primeiro benefício vira campanha/cupom nomeados;
// o array completo fica em metadata pra qualquer auditoria financeira.
const beneficios = order.benefits || [];
const primeiroBeneficio = beneficios[0] || null;
const campanhaMarketplace = primeiroBeneficio?.campaign?.name ?? null;
const cupomMarketplace = primeiroBeneficio?.campaign?.id ?? null;
// Regra de substituição do pedido (order.picking.replacementOptions) -
// relevante pra separação de pedido saber se pode oferecer substituto.
const politicaSubstituicao = order.picking?.replacementOptions ?? null;
const agendado = order.orderTiming === 'SCHEDULED';
const entregaPrevistaInicio = agendado ? (order.schedule?.deliveryDateTimeStart ?? null) : null;
const entregaPrevistaFim = agendado ? (order.schedule?.deliveryDateTimeEnd ?? null) : dataHoraImediata;
return [{
  json: {
    ...ctx,
    tipo_pagamento: tipoPagamento,
    status_pagamento: statusPagamento,
    valor_produtos: total.subTotal ?? 0,
    valor_entrega: total.deliveryFee ?? 0,
    desconto: total.benefits ?? 0,
    valor_total: total.orderAmount ?? 0,
    observacoes: observacoes.trim(),
    numero_exibicao: order.displayId ?? null,
    metadata: JSON.stringify(troco != null ? { troco } : {}),
    tipo_entrega_marketplace: order.orderType ?? null,
    telefone_localizador: order.customer?.phone?.localizer ?? null,
    telefone_localizador_expira_em: order.customer?.phone?.localizerExpiration ?? null,
    codigo_retirada_exibicao: pickupCodeEntrega,
    agendado,
    entrega_prevista_inicio: entregaPrevistaInicio,
    entrega_prevista_fim: entregaPrevistaFim,
    taxa_servico_cliente: taxaServicoCliente,
    campanha_marketplace: campanhaMarketplace,
    cupom_marketplace: cupomMarketplace,
    politica_substituicao: politicaSubstituicao,
    marketplace_metadata: JSON.stringify(beneficios.length ? { beneficios } : {}),
  },
}];

const pedidoId = $json.id;
const itens = $('Agregar itens resolvidos').item.json.itens;
return itens.map(it => ({
  json: {
    pedido_id: pedidoId,
    produto_id: it.produto_id,
    quantidade: it.quantidade,
    preco_unitario: it.preco_unitario,
    subtotal: it.subtotal,
    uniqueid_marketplace: it.uniqueid_marketplace,
    observacao_cliente: it.observacao_cliente,
  },
}));

parameters.query:
select
  (select mp.pedido_id from marketplace_pedidos mp where mp.marketplace_order_id = $1 limit 1) as pedido_id,
  (select p.status from pedidos p join marketplace_pedidos mp on mp.pedido_id = p.id where mp.marketplace_order_id = $1 limit 1) as status;

