const ev = $json;
const meta = ev.metadata || {};
return [{
  json: {
    orderId: ev.orderId || meta.orderId,
    empresa_id: ev.empresa_id,
    disputa_id_externo: meta.disputeId || ev.disputeId || ev.id,
    tipo: meta.handshakeType || meta.action || null,
    mensagem: meta.message || null,
    alternativas: meta.alternatives ? JSON.stringify(meta.alternatives) : null,
    prazo_expiracao: meta.expiresAt || ev.expiresAt || null,
  },
}];
